<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { api,errorText,hasRole } from '../api'
import { useLoad,useRequestKey } from '../composables'
import type { Page,Target,Runbook } from '../types'
import PageState from '../components/PageState.vue'
import PaginationBar from '../components/PaginationBar.vue'
const route=useRoute(),router=useRouter(),targetId=ref(String(route.query.targetId||'')),targetPage=ref(0),targets=ref<Page<Target>|null>(null),page=ref(0),creating=ref(false),title=ref(''),markdown=ref(''),busy=ref(false),saveError=ref(''),key=useRequestKey()
const {data,loading,error,load}=useLoad(async()=>{targets.value=await api<Page<Target>>(`/targets?page=${targetPage.value}&size=100`);if(!targetId.value)targetId.value=targets.value.items[0]?.id||'';return targetId.value?await api<Page<Runbook>>(`/targets/${targetId.value}/runbooks?page=${page.value}&size=20`):null})
async function choose(){page.value=0;creating.value=false;saveError.value='';await router.replace({query:{targetId:targetId.value}});await load()}
async function create(){busy.value=true;saveError.value='';try{const body={title:title.value,markdown:markdown.value};const book=await api<Runbook>(`/targets/${targetId.value}/runbooks`,{method:'POST',body,key:key.forBody({targetId:targetId.value,...body})});await router.push('/runbooks/'+book.id)}catch(e){saveError.value=errorText(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="page-heading"><div><h1>运行手册</h1><p>把处理经验发布为可追溯的版本，供值班排查与只读诊断引用。</p></div><button v-if="hasRole('OPS_ADMIN')&&targetId" class="btn primary" @click="creating=!creating">{{ creating?'收起新建':'新建手册' }}</button></div><section class="panel"><div class="panel-heading"><label>服务目标<select v-model="targetId" @change="choose"><option v-if="!targets?.items.length" value="">暂无可见目标</option><option v-for="target in targets?.items" :key="target.id" :value="target.id">{{ target.name }} · {{ target.environment }}</option></select></label><button class="btn" :disabled="loading" @click="load">刷新</button></div><PaginationBar v-if="targets&&targets.total>100" :page="targetPage" :size="100" :total="targets.total" :loading="loading" @change="p=>{targetPage=p;targetId='';load()}" /><form v-if="creating" class="inline-form" @submit.prevent="create"><h2>新建草稿</h2><div v-if="saveError" class="error-message" role="alert">{{ saveError }}</div><label>手册标题<input v-model="title" required maxlength="160" /></label><label>Markdown 正文<textarea v-model="markdown" required maxlength="24000" rows="10" placeholder="# 观测&#10;先核对检查历史。&#10;## 排查&#10;人工比较上游和部署状态。"></textarea></label><p class="form-hint">发布时按标题分段，最多 5 段、每段 6,000 字；正文不会执行脚本。</p><div class="form-actions"><button class="btn primary" :disabled="busy">{{ busy?'保存中…':'保存草稿' }}</button></div></form><PageState :loading="loading&&!data" :error="error" :empty="!loading&&!error&&(!data||!data.items.length)" title="这个目标还没有运行手册" description="管理员可先创建草稿，再发布供诊断引用。" @retry="load"><div class="table-scroll"><table><thead><tr><th>手册</th><th>发布版本</th><th>状态</th><th>草稿</th></tr></thead><tbody><tr v-for="book in data?.items" :key="book.id"><td><RouterLink :to="'/runbooks/'+book.id">{{ book.title }}</RouterLink></td><td>{{ book.latestVersion?'v'+book.latestVersion:'尚未发布' }}</td><td>{{ book.enabled?'启用':'已停用' }}</td><td>{{ book.hasUnpublishedChanges?'有未发布更改':'与发布版一致' }}</td></tr></tbody></table></div><PaginationBar v-if="data" :page="page" :size="20" :total="data.total" :loading="loading" @change="p=>{page=p;load()}" /></PageState></section></template>
